import React from 'react';
import './Projects.css';

const PROJECTS = [
  {
    title: 'ExploitXplorers',
    desc: 'A community platform for cybersecurity awareness and hands-on knowledge for students.',
    tags: ['MERN Stack', 'Cybersecurity', 'UI/UX'],
    href: '#',
    bg: '#111',
    light: false,
  },
  {
    title: 'Priscripto',
    desc: 'AI-powered medical appointment booking system designed for healthcare accessibility.',
    tags: ['AI', 'React', 'Node.js', 'MongoDB'],
    href: '#',
    bg: '#f81927',
    light: false,
  },
  {
    title: 'Hospital Booking System',
    desc: 'A comprehensive healthcare scheduling solution for booking and managing doctor appointments.',
    tags: ['MERN Stack', 'Healthcare', 'UI/UX'],
    href: '#',
    bg: '#eee',
    light: true,
  },
  {
    title: 'Blog System',
    desc: 'A dynamic space for writers and creators to share knowledge and publish articles.',
    tags: ['React', 'Express', 'Tailwind'],
    href: '#',
    bg: '#111',
    light: false,
  },
];

export default function Projects() {
  const ProjectCard = ({ proj, idx }) => (
    <div
      className="flex-none w-[280px] lg:w-[380px] flex flex-col bg-white"
    >
      <div className="aspect-video flex items-center justify-center" style={{ background: proj.bg }}>
         <span className={`font-display font-black text-2xl uppercase tracking-tighter opacity-20 ${proj.light ? 'text-black' : 'text-white'}`}>
            {proj.title}
          </span>
      </div>
      <div className="p-6 flex-1 border-t border-black">
        <h3 className="font-display text-lg lg:text-xl font-medium">{proj.title}</h3>
        <p className="text-sm mt-2 text-gray-600 line-clamp-2">{proj.desc}</p>
        <div className="mt-4 flex flex-wrap gap-2">
          {proj.tags.map((tag) => (
            <span key={tag} className="font-mono text-[9px] uppercase px-2 py-1 border border-black text-black">
              {tag}
            </span>
          ))}
        </div>
      </div>
    </div>
  );

  const ViewAllCard = () => (
    <a 
      href="https://krishsatasiya.netlify.app/" 
      target="_blank" 
      rel="noopener noreferrer"
      className="flex-none w-[280px] lg:w-[380px] bg-primary-500 hover:bg-black text-white transition-colors flex flex-col items-center justify-center p-8 text-center"
    >
      <span className="font-display font-black text-3xl lg:text-4xl uppercase tracking-tighter mb-4 leading-none">
        View All<br />Projects
      </span>
      <span className="font-mono text-[10px] uppercase border border-white px-3 py-1.5">
        Explore 15+ More
      </span>
    </a>
  );

  // Combine into a single unit to repeat for seamless scroll
  const scrollItems = [
    ...PROJECTS.map((p, i) => <ProjectCard key={`p-${i}`} proj={p} idx={i} />),
    <ViewAllCard key="view-all" />
  ];

  return (
    <section className="py-section overflow-hidden" id="projects">
      <div className="container">
        <h2 className="font-display text-3xl font-semibold lg:text-4xl">Featured Projects</h2>
        <p className="text-xl lg:text-2xl mt-2 text-gray-600">
          A selection of real-world products designed, built, and shipped.
        </p>
      </div>

      <div className="mt-12 border-y border-black bg-black">
        <div className="flex animate-scroll hover:[animation-play-state:paused] gap-[2px]">
          {/* Double everything for seamless loop */}
          {scrollItems}
          {scrollItems}
        </div>
      </div>
    </section>
  );
}
